<template><div class="page-view"><div class="welcome-row"><div><h1>Minhas tarefas</h1><p class="subcopy">{{tasks.length}} tarefa(s) encontrada(s).</p></div><button v-if="admin" class="primary-btn" @click="$emit('task')"><Plus/>Nova tarefa</button></div><section class="panel page-panel"><div class="filters full"><div class="filter-tabs"><button v-for="s in statuses" :key="s" :class="{selected:status===s}" @click="$emit('update:status',s)">{{s}}</button></div><label class="select-filter"><SlidersHorizontal/><select :value="priority" @change="$emit('update:priority',($event.target as HTMLSelectElement).value)"><option>Todas</option><option>Alta</option><option>Média</option><option>Baixa</option></select></label></div><div class="table-wrap"><table><thead><tr><th>TAREFA</th><th>RESPONSÁVEL</th><th>PRIORIDADE</th><th>PRAZO</th><th>STATUS</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id" class="click-row" @click="$emit('task',t)"><td><div class="task-title"><Avatar :member="member(t.assigneeId)"/><div><strong>{{t.title}}</strong><small>{{project(t.projectId)}}</small></div></div></td><td><div class="assignee-info"><strong>{{member(t.assigneeId)?.name||'Equipe'}}</strong><small>{{member(t.assigneeId)?.job||'Função não informada'}}</small></div></td><td><span :class="['priority',priorityClass(t.priority)]"><i/>{{t.priority}}</span></td><td>{{fmt(t.due)}}</td><td><span :class="['status',t.status==='Concluída'?'green':t.status==='Em andamento'?'blue':'gray']">{{t.status}}</span></td></tr><tr v-if="!tasks.length"><td colspan="5" class="empty">Nenhuma tarefa encontrada.</td></tr></tbody></table></div></section></div></template>
<script setup lang="ts">import{Plus,SlidersHorizontal}from"lucide-vue-next";import Avatar from"./Avatar.vue";import type{Member,Priority,Project,Status,Task}from"../stores/taskflow";const props=defineProps<{tasks:Task[];projects:Project[];members:Member[];admin:boolean;status:"Todas"|Status;priority:"Todas"|Priority}>();defineEmits(["update:status","update:priority","task"]);const statuses=["Todas","Pendente","Em andamento","Concluída"],project=(id:number)=>props.projects.find(p=>p.id===id)?.name||"—",member=(id:number)=>props.members.find(m=>m.id===id),fmt=(v:string)=>new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"short"}).format(new Date(v+"T12:00:00")),priorityClass=(p:string)=>p==="Alta"?"high":p==="Média"?"medium":"low";</script>
